catalog_script_client.script:
function onLoad() {
    // 仅在查看模式添加按钮
    if (g_form.getView() !== 'view') return;

    // 添加按钮
    g_form.addButton('generate_pdf', '生成PDF');
    g_form.setButtonStyle('generate_pdf', 'background-color:#e53e3e;color:white;padding:4px 10px;border-radius:4px;');

    // 绑定点击事件
    addLoadEvent(function() {
        var button = document.getElementById('generate_pdf');
        if (button) {
            button.onclick = function() {
                generatePDF();
            };
        }
    });
}

function generatePDF() {
    try {
        // 收集表单数据
        var formData = {
            number: g_form.getValue('number'),
            short_description: g_form.getValue('short_description'),
            requested_for: g_form.getDisplayValue('requested_for'),
            opened_at: g_form.getDisplayValue('opened_at'),
            state: g_form.getDisplayValue('state'),
            category: g_form.getDisplayValue('category'),
            subcategory: g_form.getDisplayValue('subcategory'),
            priority: g_form.getDisplayValue('priority'),
            assignment_group: g_form.getDisplayValue('assignment_group'),
            assigned_to: g_form.getDisplayValue('assigned_to'),
            description: g_form.getDisplayValue('description')
        };

        // 生成HTML模板
        var htmlTemplate = `
            <html>
            <head>
                <style>
                    body { font-family: Arial, sans-serif; padding: 20px; }
                    h1 { color: #333; border-bottom: 2px solid #ccc; padding-bottom: 10px; }
                    .section { margin-bottom: 20px; }
                    .field { margin-bottom: 10px; }
                    .label { font-weight: bold; width: 150px; display: inline-block; }
                    .value { color: #555; }
                    .description { white-space: pre-wrap; }
                </style>
            </head>
            <body>
                <h1>服务请求详情 - ${formData.number}</h1>

                <div class="section">
                    <div class="field"><span class="label">请求编号:</span> <span class="value">${formData.number}</span></div>
                    <div class="field"><span class="label">请求人:</span> <span class="value">${formData.requested_for}</span></div>
                    <div class="field"><span class="label">创建日期:</span> <span class="value">${formData.opened_at}</span></div>
                    <div class="field"><span class="label">状态:</span> <span class="value">${formData.state}</span></div>
                    <div class="field"><span class="label">优先级:</span> <span class="value">${formData.priority}</span></div>
                </div>

                <div class="section">
                    <h2>请求明细</h2>
                    <div class="field"><span class="label">类别:</span> <span class="value">${formData.category}</span></div>
                    <div class="field"><span class="label">子类别:</span> <span class="value">${formData.subcategory}</span></div>
                    <div class="field"><span class="label">分配组:</span> <span class="value">${formData.assignment_group}</span></div>
                    <div class="field"><span class="label">负责人:</span> <span class="value">${formData.assigned_to}</span></div>
                </div>

                <div class="section">
                    <h2>描述</h2>
                    <div class="description">${formData.description}</div>
                </div>

                <div class="section">
                    <p style="color: #777; font-size: 12px;">生成时间: ${new Date().toLocaleString()}</p>
                </div>
            </body>
            </html>
        `;

        // 使用ServiceNow内置工具将HTML转换为PDF
        var pdf = new sn_pdf.HTMLToPDF(htmlTemplate);
        pdf.setTitle("服务请求详情 - " + formData.number);

        // 获取PDF内容（Base64编码）
        var pdfContent = pdf.getBase64Content();

        // 创建下载链接
        var link = document.createElement('a');
        link.href = 'data:application/pdf;base64,' + pdfContent;
        link.download = 'Service_Request_' + formData.number + '.pdf';
        link.style.display = 'none';

        // 触发下载
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

    } catch (e) {
        alert('生成PDF时出错: ' + e);
        console.error('PDF Generation Error:', e);
    }
}
